head.script:
scwin.onpageload = function() {
	var element = document.querySelector('.w2multiselect_acc_link');
    console.log('tabindex',element.getAttribute("tabindex"));
};

	scwin.checkVal1 = function() {
		return document.getElementsByClassName('w2multiselect_acc_link')[0].getAttribute('tabindex') === null;
	}
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_1_li_item_0').click()");
		WebSquare.wUnit.addCommand("pause", "400");				
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "500");

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
